local WM=100,48,51,50,97,56,99,49,50,98,50,99,54,50,98,51,52,100,52,49,54,98,49,50,98,101,50,52,101,56,55,102
local KY={46,234,189,139,7,60,46,23}
local K2={157,68,26,168,118,102,136}
local SK={7,87,56,205,205}
local HX=""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""
local sb,sc=string.byte,string.char
local function DEC(h,k)
local n=#h
local m={}
local i=1
while i<n do
local hi=sb(h,i)
local lo=sb(h,i+1)
hi=(hi>=97) and (hi-87) or ((hi>=65) and (hi-55) or (hi-48))
lo=(lo>=97) and (lo-87) or ((lo>=65) and (lo-55) or (lo-48))
local v=hi*16+lo
local kk=k[((i-1)/2)%#k+1]
local r,p=0,1
local x,y=v,kk
while x>0 or y>0 do
local xa,ya=x%2,y%2
if xa~=ya then r=r+p end
x=(x-xa)/2 y=(y-ya)/2 p=p*2
end
m[#m+1]=sc(r)
i=i+2
end
return table.concat(m)
end
local L1=DEC(HX,KY)
local function DEC2(s,k)
local o={}
for i=1,#s do
local b=sb(s,i)
local kk=k[(i-1)%#k+1]
local mix=((i-1)*31)%256
local r,q=0,1
local x,y=b,kk
while x>0 or y>0 do
local xa,ya=x%2,y%2
if xa~=ya then r=r+q end
x=(x-xa)/2 y=(y-ya)/2 q=q*2
end
local r2,q2=0,1
local x2,y2=r,mix
while x2>0 or y2>0 do
local xa,ya=x2%2,y2%2
if xa~=ya then r2=r2+q2 end
x2=(x2-xa)/2 y2=(y2-ya)/2 q2=q2*2
end
o[#o+1]=sc(r2)
end
return table.concat(o)
end
local P=DEC2(L1,K2)
local F, OM
do
local fn=loadstring(P)
if not fn then return end
F, OM = fn()
end
local ENV = getfenv and getfenv(0) or _G
local tunpack, tpack = table.unpack, table.pack
local mfloor, bnot = math.floor, ((bit32 and bit32.bnot) or function(x) return x end)
local VM
local STRDEC
local USE_STRDEC = false
if SK and #SK > 0 then
USE_STRDEC = true
local sb, sc = string.byte, string.char
STRDEC = function(s)
local o = {}
for j = 1, #s do
local b = sb(s, j)
local kk = SK[(j - 1) % #SK + 1]
local r, q = 0, 1
local x, y = b, kk
while x > 0 or y > 0 do
local xa, ya = x % 2, y % 2
if xa ~= ya then r = r + q end
x = (x - xa) / 2
y = (y - ya) / 2
q = q * 2
end
o[j] = sc(r)
end
return table.concat(o)
end
end
local function GUARD()
local need = { 'table', 'string', 'math', 'type', 'pcall', 'select' }
for i = 1, #need do
if _G[need[i]] == nil then return false end
end
local tb = _G.table
if tb.unpack == nil and unpack == nil then return false end
if debug and debug.info then
local ok = pcall(function()
local info = debug.info(1, 's')
return type(info) == 'string'
end)
if not ok then return false end
end
return true
end
local function FINGER(F)
local n = 0
local h = 0
for k, v in pairs(F) do
n = n + 1
h = (h + #v.O + #v.k * 7) % 65521
end
return n, h
end
local function INIT_OMAP()
for _, proto in pairs(F) do
if type(proto) == 'table' then
local O = proto.O
if type(O) == 'table' then
for i = 1, #O do
local v = OM[O[i]]
if v then O[i] = v end
end
end
end
end
end
VM = function(fidx, parentU, ...)
local proto = F[fidx]
local K = proto.k
local O, AA, BB, CC = proto.O, proto.A, proto.B, proto.C
local N = proto.n
local U = parentU or {}
local R = table.create and table.create(proto.m) or {}
local BX = {}
local bz = proto.b
if bz and #bz > 0 then
for i = 1, #bz do BX[bz[i]] = {v = nil} end
end
local pa = proto.a
if pa then
for i = 1, #pa do R[pa[i]] = (select(i, ...)) end
end
local PC = 1
local F_ = F
while PC <= N do
local op = O[PC]
local a  = AA[PC]
local b  = BB[PC]
local c  = CC[PC]
PC = PC + 1
if op == 4 then R[a] = R[b]
elseif op == 1 then
local kc = proto.kc
if kc then
local ci = b + 1
local cv = kc[ci]
if cv == nil then
local raw = K[ci]
if type(raw) == 'string' then
cv = STRDEC(raw)
kc[ci] = cv
else
cv = raw
end
end
R[a] = cv
else
R[a] = K[b + 1]
end
elseif op == 51 then R[a] = R[b][K[c + 1]]
elseif op == 52 then R[a][K[b + 1]] = R[c]
elseif op == 96 then R[a] = ENV[K[b + 1]]
elseif op == 98 then
local bx = U[b + 1]
R[a] = bx and bx.v
elseif op == 68 then
local bx = BX[b]
R[a] = bx and bx.v
elseif op == 16 then R[a] = R[b] + R[c]
elseif op == 17 then R[a] = R[b] - R[c]
elseif op == 18 then R[a] = R[b] * R[c]
elseif op == 26 then R[a] = (R[b] < R[c])
elseif op == 24 then R[a] = (R[b] == R[c])
elseif op == 32 then R[a] = not R[b]
elseif op == 30 then R[a] = R[b] and R[c]
elseif op == 31 then R[a] = R[b] or R[c]
elseif op == 27 then R[a] = (R[b] <= R[c])
elseif op == 25 then R[a] = (R[b] ~= R[c])
elseif op == 28 then R[a] = (R[b] > R[c])
elseif op == 29 then R[a] = (R[b] >= R[c])
elseif op == 19 then R[a] = R[b] / R[c]
elseif op == 20 then R[a] = R[b] % R[c]
elseif op == 21 then R[a] = R[b] ^ R[c]
elseif op == 22 then R[a] = mfloor(R[b] / R[c])
elseif op == 23 then R[a] = R[b] .. R[c]
elseif op == 33 then R[a] = -R[b]
elseif op == 34 then R[a] = #R[b]
elseif op == 35 then R[a] = bnot(R[b])
elseif op == 2 then R[a] = nil
elseif op == 3 then R[a] = (b == 1)
elseif op == 69 then
local bx = BX[a]
if bx then bx.v = R[b] end
elseif op == 49 then R[a] = R[b][R[c]]
elseif op == 50 then R[a][R[b]] = R[c]
elseif op == 48 then R[a] = {}
elseif op == 97 then ENV[K[b + 1]] = R[a]
elseif op == 99 then
local bx = U[a + 1]
if bx then bx.v = R[b] end
elseif op == 114 then
local ki = c + 1
local kv = K[ki]
if kc then
local cv = kc[ki]
if cv == nil then
cv = (type(kv) == 'string') and STRDEC(kv) or kv
kc[ki] = cv
end
kv = cv
end
local o = R[b]
R[a] = o[kv]
R[a + 1] = o
elseif op == 80 then PC = PC + b
elseif op == 82 then
local v = R[a]
if not v or v == false then PC = PC + b end
elseif op == 81 then
local v = R[a]
if v and v ~= false then PC = PC + b end
elseif op == 64 or op == 67 then
local fn, n = R[b], c
if type(fn) == 'function' then
if n == 0 then
if op == 67 then
local r1, r2, r3 = fn()
R[a] = r1; R[a + 1] = r2; R[a + 2] = r3
else R[a] = fn() end
elseif n == 1 then
if op == 67 then
local r1, r2, r3 = fn(R[b + 1])
R[a] = r1; R[a + 1] = r2; R[a + 2] = r3
else R[a] = fn(R[b + 1]) end
elseif n == 2 then
if op == 67 then
local r1, r2, r3 = fn(R[b + 1], R[b + 2])
R[a] = r1; R[a + 1] = r2; R[a + 2] = r3
else R[a] = fn(R[b + 1], R[b + 2]) end
elseif n == 3 then
if op == 67 then
local r1, r2, r3 = fn(R[b + 1], R[b + 2], R[b + 3])
R[a] = r1; R[a + 1] = r2; R[a + 2] = r3
else R[a] = fn(R[b + 1], R[b + 2], R[b + 3]) end
else
local args = {}
for i = 1, n do args[i] = R[b + i] end
if op == 67 then
local r = tpack(fn(tunpack(args, 1, n)))
for i = 1, 6 do R[a + i - 1] = r[i] end
else R[a] = fn(tunpack(args, 1, n)) end
end
else R[a] = nil end
elseif op == 65 then
local fn, n = R[b], c
if type(fn) == 'function' then
if n == 1 then R[a] = fn(R[b + 1])
elseif n == 2 then R[a] = fn(R[b + 1], R[b + 2])
elseif n == 3 then R[a] = fn(R[b + 1], R[b + 2], R[b + 3])
else
local args = {}
for i = 1, n do args[i] = R[b + i] end
R[a] = fn(tunpack(args, 1, n))
end
else R[a] = nil end
elseif op == 66 then
if b == 0 then return end
if b == 1 then return R[a] end
if b == 2 then return R[a], R[a + 1] end
if b == 3 then return R[a], R[a + 1], R[a + 2] end
local out = {}
for i = 0, b - 1 do out[i + 1] = R[a + i] end
return tunpack(out, 1, b)
elseif op == 100 then
local fi = b
local desc = F_[fi].u
local cu = {}
for i = 1, #desc do
local d = desc[i]
if d > 0 then
local slot = d - 1
local bx = BX[slot]
if bx == nil then bx = {v = R[slot]}; BX[slot] = bx end
cu[i] = bx
elseif d < 0 then
cu[i] = U[-d]
end
end
R[a] = function(...) return VM(fi, cu, ...) end
elseif op == 112 then
if b == 1 then R[a] = (select(1, ...))
else
for i = 1, b do R[a + i - 1] = (select(i, ...)) end
end
end
end
end
INIT_OMAP()
local _n, _h = FINGER(F)
if _n < 1 then return end
if not GUARD() then return end
return VM(1, nil)